// Independent specification queues; no DUT implementation state is modeled.
reg armed = 0;
reg reset_post = 0;
reg [5:0] saved_ok = 6'b111111;
reg [7:0] bytes_q [0:127];
reg lasts_q [0:127];
reg [33:0] headers_q [0:31];
reg [6:0] bw = 0, br = 0;
reg [5:0] bc = 0;
reg [4:0] hw = 0, hr = 0;
reg [5:0] hc = 0;
reg [3:0] in_len = 0;
reg overflow = 0;
reg ms = 0, hs = 0, ss = 0;
reg [8:0] mp;
reg [33:0] hp;
reg [8:0] sp;
reg [7:0] tail = 0;
reg [5:0] check_now;
integer k;
integer add_bytes;
integer out_length;
reg [7:0] next_count;
wire [33:0] header_now = {h_pad,h_truncate,h_length,h_original_length};
wire [8:0] data_now = {m_last,m_data};
wire [8:0] source_now = {s_last,s_data};

always @* begin
    check_now = 6'b111111;
    if (armed) begin
        // Presented responses are checked even when their ready is low.
        check_now[0] = ((m_valid == 0) || (m_valid == 1));
        if (m_valid !== 1'b0) begin
            if (bc == 0) check_now[0] = (m_valid == 0);
            else check_now[0] = check_now[0] &
                (m_data == bytes_q[br]) & (m_last == lasts_q[br]);
        end
        check_now[1] = ((h_valid == 0) || (h_valid == 1));
        if (h_valid !== 1'b0) begin
            if (hc == 0) check_now[1] = (h_valid == 0);
            else check_now[1] = check_now[1] & (header_now == headers_q[hr]);
        end
        if (!reset_post && rst !== 1'b1) begin
            if (ms) check_now[2] = check_now[2] & (m_valid == 1) & (data_now == mp);
            if (hs) check_now[2] = check_now[2] & (h_valid == 1) & (header_now == hp);
        end
        if (reset_post) begin
            check_now[3] = (m_valid == 0) & (h_valid == 0);
        end
        check_now[4] = ((rst == 0) || (rst == 1)) &
                      ((s_valid == 0) || (s_valid == 1)) &
                      ((s_ready == 0) || (s_ready == 1)) &
                      ((m_ready == 0) || (m_ready == 1)) &
                      ((h_ready == 0) || (h_ready == 1));
        if (rst === 1'b1) check_now[4] = check_now[4] & (s_valid == 0);
        if (rst !== 1'b1 && ss)
            check_now[4] = check_now[4] & (s_valid == 1) & (source_now == sp);
        if (rst === 1'b0 && s_valid === 1'b1 && s_ready === 1'b1) begin
            check_now[4] = check_now[4] & ((s_last == 0) || (s_last == 1)) &
                          ((^s_data) == (^s_data));
            if (in_len == 11) check_now[4] = check_now[4] & (s_last == 1);
        end
        if (overflow) check_now[5] = 1'bx;
        if (trace_done === 1'b1) begin
            check_now[5] = check_now[5] & (rst == 0) & (s_valid == 0) &
                (m_valid == 0) & (h_valid == 0) & (in_len == 0) &
                (bc == 0) & (hc == 0);
            // A short quiet tail does not establish finite completion.
            if (tail < 32 && check_now[5] !== 1'b0) check_now[5] = 1'bx;
        end
    end
end
assign active = {6{armed}};
assign ok = saved_ok & check_now;

always @(posedge clk) begin
    armed <= 1'b1;
    saved_ok <= saved_ok & check_now;
    reset_post <= (rst === 1'b1);
    if (rst === 1'b1) begin
        bw <= 0; br <= 0; bc <= 0;
        hw <= 0; hr <= 0; hc <= 0;
        in_len <= 0;
        ms <= 0; hs <= 0; ss <= 0;
        tail <= 0;
        overflow <= 0;
    end else if (rst === 1'b0) begin
        ms <= (m_valid === 1'b1 && m_ready === 1'b0);
        hs <= (h_valid === 1'b1 && h_ready === 1'b0);
        ss <= (s_valid === 1'b1 && s_ready === 1'b0);
        mp <= data_now;
        hp <= header_now;
        sp <= source_now;
        if (s_valid === 1'b0 && m_ready === 1'b1 && h_ready === 1'b1) begin
            if (tail != 255) tail <= tail + 1'b1;
        end else tail <= 0;
        add_bytes = 0;
        if (s_valid === 1'b1 && s_ready === 1'b1) begin
            if (in_len < 8) add_bytes = 1;
            if (s_last === 1'b1 && in_len < 3) add_bytes = 4-in_len;
            if (bc + add_bytes <= 63) begin
                if (in_len < 8) begin
                    bytes_q[bw] <= s_data;
                    lasts_q[bw] <= (in_len == 7) ? 1'b1 :
                        ((in_len >= 3) ? s_last : 1'b0);
                end
                for (k=1; k<4; k=k+1) begin
                    if (k < add_bytes) begin
                        bytes_q[(bw+k)&127] <= 0;
                        lasts_q[(bw+k)&127] <= (k == add_bytes-1);
                    end
                end
                bw <= bw + add_bytes;
            end else overflow <= 1;
            if (s_last === 1'b1) begin
                out_length = in_len+1;
                if (out_length < 4) out_length = 4;
                if (out_length > 8) out_length = 8;
                if (hc < 32) begin
                    headers_q[hw] <= { (in_len < 3), (in_len >= 8),
                        16'(out_length), 16'(in_len+1) };
                    hw <= hw + 1'b1;
                end else overflow <= 1;
                in_len <= 0;
            end else if (in_len < 12) in_len <= in_len + 1'b1;
            else overflow <= 1;
        end
        next_count = bc + add_bytes;
        if (m_valid === 1'b1 && m_ready === 1'b1 && bc != 0) begin
            br <= br + 1'b1;
            next_count = next_count - 1;
        end
        if (next_count <= 63) bc <= next_count[5:0];
        else overflow <= 1;
        case ({(s_valid === 1'b1 && s_ready === 1'b1 && s_last === 1'b1),
               (h_valid === 1'b1 && h_ready === 1'b1 && hc != 0)})
            2'b10: if (hc < 32) hc <= hc+1'b1;
            2'b01: hc <= hc-1'b1;
            default: hc <= hc;
        endcase
        if (h_valid === 1'b1 && h_ready === 1'b1 && hc != 0) hr <= hr+1'b1;
    end else begin
        saved_ok <= saved_ok & check_now & 6'bxxxxxx;
    end
end

// Bounded public-pin scoreboard. Queue heads describe presented beats,
// not merely beats for which the consumer happens to be ready.
reg seen = 0;
reg reset_edge = 0;
reg [5:0] failed = 0;
reg [7:0] data_q [0:127];
reg last_q [0:127];
reg [6:0] dw = 0, dr = 0;
reg [7:0] dc = 0;
reg [33:0] hdr_q [0:31];
reg [4:0] hw = 0, hr = 0;
reg [5:0] hc = 0;
reg [3:0] in_len = 0;
reg hold_m = 0, hold_h = 0, hold_s = 0;
reg [8:0] saved_m = 0;
reg [33:0] saved_h = 0;
reg [8:0] saved_s = 0;
reg [7:0] tail = 0;
reg [5:0] bad;
integer k;
integer add_data;
integer length_now;
reg [15:0] adjusted;
wire take_s = (rst === 1'b0) && (s_valid === 1'b1) && (s_ready === 1'b1);
wire take_m = (rst === 1'b0) && (m_valid === 1'b1) && (m_ready === 1'b1);
wire take_h = (rst === 1'b0) && (h_valid === 1'b1) && (h_ready === 1'b1);
wire [33:0] header_value = {h_pad,h_truncate,h_length,h_original_length};

always @* begin
    length_now = in_len + 1;
    add_data = 0;
    adjusted = 16'd8;
    if (length_now < 4) adjusted = 16'd4;
    else if (length_now <= 8) adjusted = length_now;
    if (take_s) begin
        if (in_len < 8) add_data = 1;
        if ((s_last === 1'b1) && (length_now < 4))
            add_data = 5-length_now;
    end
end

always @* begin
    bad = 0;
    if (seen) begin
        // Known controls are required even when payload is disabled.
        if (((rst !== 1'b0) && (rst !== 1'b1)) ||
            ((s_valid !== 1'b0) && (s_valid !== 1'b1)) ||
            ((s_ready !== 1'b0) && (s_ready !== 1'b1)) ||
            ((m_ready !== 1'b0) && (m_ready !== 1'b1)) ||
            ((h_ready !== 1'b0) && (h_ready !== 1'b1)) ||
            ((m_valid !== 1'b0) && (m_valid !== 1'b1)) ||
            ((h_valid !== 1'b0) && (h_valid !== 1'b1))) bad[4] = 1;
        if (s_valid === 1'b1) begin
            if ((^s_data === 1'bx) ||
                ((s_last !== 1'b0) && (s_last !== 1'b1))) bad[4] = 1;
            if (rst === 1'b1) bad[4] = 1;
        end
        if ((rst === 1'b0) && hold_s &&
            ((s_valid !== 1'b1) || ({s_last,s_data} !== saved_s))) bad[4] = 1;
        if (reset_edge) begin
            if ((m_valid !== 1'b0) || (h_valid !== 1'b0)) bad[3] = 1;
        end else begin
            if (m_valid === 1'b1) begin
                if (dc == 0) begin
                    bad[0] = 1;
                    bad[1] = 1;
                end else begin
                    if ((^m_data === 1'bx) || (m_data !== data_q[dr])) bad[0] = 1;
                    if (((m_last !== 1'b0) && (m_last !== 1'b1)) ||
                        (m_last !== last_q[dr])) bad[1] = 1;
                end
            end
            if (h_valid === 1'b1) begin
                if ((hc == 0) || (^header_value === 1'bx)) bad[2] = 1;
                else if (header_value !== hdr_q[hr]) bad[2] = 1;
            end
            if (rst === 1'b0) begin
                if (hold_m && ((m_valid !== 1'b1) ||
                    ({m_last,m_data} !== saved_m))) bad[3] = 1;
                if (hold_h && ((h_valid !== 1'b1) ||
                    (header_value !== saved_h))) bad[3] = 1;
            end
        end
        if (take_s && (length_now > 12)) bad[4] = 1;
        // Exhaustion never silently overwrites a live obligation.
        if (take_s && (dc + add_data > 128)) bad[4] = 1;
        if (take_s && (s_last === 1'b1) && (hc == 32) && !take_h) bad[4] = 1;
    end
end

always @(posedge clk) begin
    seen <= 1;
    failed <= failed | bad;
    reset_edge <= (rst === 1'b1);
    if (rst === 1'b1) begin
        dw <= 0; dr <= 0; dc <= 0;
        hw <= 0; hr <= 0; hc <= 0;
        in_len <= 0;
        hold_m <= 0; hold_h <= 0; hold_s <= 0;
        tail <= 0;
    end else if (rst === 1'b0) begin
        hold_m <= (m_valid === 1'b1) && (m_ready === 1'b0);
        hold_h <= (h_valid === 1'b1) && (h_ready === 1'b0);
        hold_s <= (s_valid === 1'b1) && (s_ready === 1'b0);
        saved_m <= {m_last,m_data};
        saved_h <= header_value;
        saved_s <= {s_last,s_data};
        if ((s_valid === 1'b0) && (m_ready === 1'b1) && (h_ready === 1'b1)) begin
            if (tail < 128) tail <= tail + 1'b1;
        end else tail <= 0;
        if (take_s) begin
            if (in_len < 8) begin
                data_q[dw] <= s_data;
                last_q[dw] <= (in_len == 7) || ((s_last === 1'b1) && (length_now >= 4));
            end
            if ((s_last === 1'b1) && (length_now < 4)) begin
                for (k=1; k<4; k=k+1) begin
                    if (k <= 4-length_now) begin
                        data_q[(dw+k)&127] <= 0;
                        last_q[(dw+k)&127] <= (k == 4-length_now);
                    end
                end
            end
            dw <= dw + add_data;
            if (s_last === 1'b1) begin
                hdr_q[hw] <= { (length_now < 4), (length_now > 8), adjusted, 16'(length_now) };
                hw <= hw + 1'b1;
                in_len <= 0;
            end else if (in_len < 15) in_len <= in_len + 1'b1;
        end
        if (take_m && (dc != 0)) dr <= dr + 1'b1;
        if (take_h && (hc != 0)) hr <= hr + 1'b1;
        dc <= dc + add_data - ((take_m && (dc != 0)) ? 1 : 0);
        hc <= hc + ((take_s && (s_last === 1'b1)) ? 1 : 0)
                 - ((take_h && (hc != 0)) ? 1 : 0);
    end
end

wire end_bad = (dc != 0) || (hc != 0) || (in_len != 0) ||
               (s_valid !== 1'b0) || (m_valid !== 1'b0) || (h_valid !== 1'b0) ||
               (rst !== 1'b0) || (m_ready !== 1'b1) || (h_ready !== 1'b1) ||
               (tail < 32);
assign active[4:0] = {5{seen}};
assign active[5] = (trace_done === 1'b1);
assign ok[4:0] = ~(failed[4:0] | bad[4:0]);
// No clock is required after the final-post marker.
assign ok[5] = !end_bad;

// Private, bounded specification scoreboard. No DUT state is referenced.
reg armed = 1'b0;
reg reset_post = 1'b0;
reg [5:0] bad = 0;
reg [5:0] fail_now;
reg [6:0] iw = 0, dr = 0, hr = 0;
reg [3:0] ip = 0, dp = 0;
reg [63:0] bytes_q [0:63];
reg [3:0] size_q [0:63];
reg [63:0] complete_q = 0;
reg ms = 0, hs = 0;
reg [8:0] saved_m = 0;
reg [33:0] saved_h = 0;
reg [7:0] tail = 0;
wire [6:0] data_distance = iw-dr;
wire [6:0] header_distance = iw-hr;
wire data_exists = (data_distance != 0) || (ip != 0);
wire header_exists = header_distance != 0;
reg [3:0] dn, out_len;
reg [7:0] expected_byte;
reg expected_last, byte_known;
reg [15:0] hn, hl;
reg [33:0] expected_header;
integer k;

always @* begin
    dn = 0;
    if (data_distance != 0) dn = size_q[dr[5:0]];
    else dn = ip;
    if (dn < 4) out_len = 4;
    else if (dn > 8) out_len = 8;
    else out_len = dn;
    byte_known = 0;
    expected_byte = 0;
    expected_last = 0;
    if (data_exists && dp < 8) begin
        if (dp < dn) begin
            byte_known = 1;
            expected_byte = bytes_q[dr[5:0]][dp*8 +: 8];
        end else if (data_distance != 0 && dp < out_len) begin
            byte_known = 1;
            expected_byte = 0;
        end
        if (dp == 7) expected_last = 1;
        else if (data_distance != 0) expected_last = (dp == out_len-1);
    end
    hn = 0;
    hl = 0;
    expected_header = 0;
    if (header_exists) begin
        hn = {12'd0,size_q[hr[5:0]]};
        if (hn < 4) hl = 4;
        else if (hn > 8) hl = 8;
        else hl = hn;
        expected_header = {(hn < 4),(hn > 8),hl,hn};
    end

    fail_now = 0;
    if (armed) begin
        // Presented outputs are checked even when their sinks are blocked.
        if (m_valid !== 1'b0 && m_valid !== 1'b1) fail_now[0] = 1;
        if (m_valid === 1'b1) begin
            if (!byte_known) fail_now[0] = 1;
            else begin
                if ((^m_data === 1'bx) || (^expected_byte === 1'bx) ||
                    m_data !== expected_byte) fail_now[0] = 1;
                if (m_last !== expected_last) fail_now[0] = 1;
            end
        end
        if (h_valid !== 1'b0 && h_valid !== 1'b1) fail_now[1] = 1;
        if (h_valid === 1'b1) begin
            if (!header_exists) fail_now[1] = 1;
            else if ((^{h_pad,h_truncate,h_length,h_original_length} === 1'bx) ||
                {h_pad,h_truncate,h_length,h_original_length} !== expected_header)
                fail_now[1] = 1;
        end
        // The previous edge's blocked response must survive into this sample.
        if (!reset_post) begin
            if (ms && (m_valid !== 1'b1 ||
                {m_data,m_last} !== saved_m || ^{m_data,m_last} === 1'bx))
                fail_now[2] = 1;
            if (hs && (h_valid !== 1'b1 ||
                {h_pad,h_truncate,h_length,h_original_length} !== saved_h ||
                ^{h_pad,h_truncate,h_length,h_original_length} === 1'bx))
                fail_now[2] = 1;
        end
        if (reset_post && (m_valid !== 1'b0 || h_valid !== 1'b0))
            fail_now[3] = 1;
        // Meaningful accepted input observations and bounded inventory.
        if (rst !== 1'b0 && rst !== 1'b1) fail_now[4] = 1;
        if (rst === 1'b0) begin
            if (s_valid !== 1'b0 && s_valid !== 1'b1) fail_now[4] = 1;
            if (s_valid === 1'b1) begin
                if (s_ready !== 1'b0 && s_ready !== 1'b1) fail_now[4] = 1;
                if (s_ready === 1'b1) begin
                    if ((^s_data === 1'bx) ||
                        (s_last !== 1'b0 && s_last !== 1'b1)) fail_now[4] = 1;
                    if (ip >= 12 || (ip == 11 && s_last !== 1'b1)) fail_now[4] = 1;
                    if (data_distance >= 63 || header_distance >= 63) fail_now[4] = 1;
                end
            end
            if (m_valid === 1'b1 && m_ready !== 1'b0 && m_ready !== 1'b1)
                fail_now[4] = 1;
            if (h_valid === 1'b1 && h_ready !== 1'b0 && h_ready !== 1'b1)
                fail_now[4] = 1;
        end
        if (trace_done === 1'b1) begin
            if (tail < 32 || rst !== 1'b0 || s_valid !== 1'b0 ||
                m_valid !== 1'b0 || h_valid !== 1'b0 ||
                ip != 0 || dp != 0 || iw != dr || iw != hr)
                fail_now[5] = 1;
        end
    end
end

always @(posedge clk) begin
    armed <= 1;
    if (armed) bad <= bad | fail_now;
    reset_post <= (rst === 1'b1);
    if (rst === 1'b1) begin
        iw <= 0;
        dr <= 0;
        hr <= 0;
        ip <= 0;
        dp <= 0;
        complete_q <= 0;
        ms <= 0;
        hs <= 0;
        tail <= 0;
    end else if (rst === 1'b0) begin
        if (s_valid === 1'b0 && m_ready === 1'b1 && h_ready === 1'b1) begin
            if (tail != 255) tail <= tail+1'b1;
        end else tail <= 0;
        ms <= (m_valid === 1'b1 && m_ready === 1'b0);
        hs <= (h_valid === 1'b1 && h_ready === 1'b0);
        saved_m <= {m_data,m_last};
        saved_h <= {h_pad,h_truncate,h_length,h_original_length};
        if (s_valid === 1'b1 && s_ready === 1'b1 && ip < 12 &&
            data_distance < 63 && header_distance < 63) begin
            if (ip < 8) bytes_q[iw[5:0]][ip*8 +: 8] <= s_data;
            if (s_last === 1'b1) begin
                size_q[iw[5:0]] <= ip+1'b1;
                complete_q[iw[5:0]] <= 1;
                iw <= iw+1'b1;
                ip <= 0;
            end else ip <= ip+1'b1;
        end
        if (m_valid === 1'b1 && m_ready === 1'b1 && byte_known) begin
            if (expected_last) begin
                dr <= dr+1'b1;
                dp <= 0;
            end else dp <= dp+1'b1;
        end
        if (h_valid === 1'b1 && h_ready === 1'b1 && header_exists)
            hr <= hr+1'b1;
    end
end

assign active[0] = armed;
assign active[1] = armed;
assign active[2] = armed;
assign active[3] = armed;
assign active[4] = armed;
assign active[5] = armed && ((trace_done === 1'b1) || bad[5]);
assign ok = ~(bad | fail_now);

// Bounded, specification-level queues; no DUT implementation state is used.
reg started = 0;
reg reset_post = 0;
reg [5:0] failed = 0;
reg lost = 0;
reg [7:0] bytes_q [0:63][0:7];
reg [3:0] length_q [0:63];
reg complete_q [0:63];
reg [6:0] write_seq = 0, data_seq = 0, header_seq = 0;
reg [3:0] data_pos = 0;
reg data_hold = 0, header_hold = 0;
reg [8:0] saved_data;
reg [33:0] saved_header;
reg [5:0] violation;
reg data_available, boundary_known, expected_last;
reg [7:0] expected_data;
reg [3:0] adjusted_length;
wire [5:0] wi = write_seq[5:0];
wire [5:0] di = data_seq[5:0];
wire [5:0] hi = header_seq[5:0];
wire [6:0] data_distance = write_seq-data_seq;
wire [6:0] header_distance = write_seq-header_seq;
integer i;

always @* begin
    violation = 0;
    data_available = 0;
    boundary_known = 0;
    expected_last = 0;
    expected_data = 0;
    adjusted_length = 0;
    if (started && !lost) begin
        if ((data_distance < 64) && (length_q[di] != 0)) begin
            if (data_pos < length_q[di] && data_pos < 8) begin
                data_available = 1;
                expected_data = bytes_q[di][data_pos[2:0]];
            end else if (complete_q[di] && length_q[di] < 4 && data_pos < 4) begin
                data_available = 1;
                expected_data = 0;
            end
            if (data_pos < 3) begin
                boundary_known = 1;
                expected_last = 0;
            end else if (data_pos == 7) begin
                boundary_known = 1;
                expected_last = 1;
            end else if (complete_q[di]) begin
                boundary_known = 1;
                expected_last = (data_pos+1 == length_q[di]);
                if (length_q[di] < 4) expected_last = (data_pos == 3);
            end else if (length_q[di] > data_pos+1) begin
                boundary_known = 1;
                expected_last = 0;
            end
        end
        if (!reset_post) begin
            if (m_valid == 1'b1) begin
                violation[0] = !data_available;
                if (data_available) violation[0] = !(m_data == expected_data);
                if (boundary_known) violation[1] = !(m_last == expected_last);
                else violation[1] = 1'bx;
            end else if (m_valid !== 1'b0) begin
                violation[0] = 1'bx;
                violation[1] = 1'bx;
            end
            if (h_valid == 1'b1) begin
                if (!(header_distance < 64 && complete_q[hi])) violation[2] = 1;
                else begin
                    adjusted_length = length_q[hi];
                    if (length_q[hi] < 4) adjusted_length = 4;
                    if (length_q[hi] > 8) adjusted_length = 8;
                    violation[2] = !((h_original_length == {12'd0,length_q[hi]}) &&
                        (h_length == {12'd0,adjusted_length}) &&
                        (h_pad == (length_q[hi] < 4)) &&
                        (h_truncate == (length_q[hi] > 8)));
                end
            end else if (h_valid !== 1'b0) violation[2] = 1'bx;
        end
        // A synchronous reset cancels holds, but not prior failures.
        if (rst == 1'b0) begin
            if (data_hold) violation[3] = !((m_valid == 1'b1) && ({m_last,m_data} == saved_data));
            if (header_hold) violation[3] = violation[3] | !((h_valid == 1'b1) &&
                ({h_pad,h_truncate,h_length,h_original_length} == saved_header));
        end
