assign active = {trace_done === 1'b1,seen,seen,seen,seen,seen};
assign ok = live & ~failed;

always @(posedge clk) begin
    seen <= 1;
    failed <= failed | ~live;
    reset_post <= (rst === 1'b1);
    if (rst === 1'b1) begin
        bw <= 0; br <= 0; hw <= 0; hr <= 0;
        in_len <= 0;
        mh <= 0; hh <= 0;
