        if (s_valid === 1'b1 && s_ready !== 1'b0 && s_ready !== 1'b1)
            failed[4] <= 1;
        if (m_valid === 1'b1 && m_ready !== 1'b0 && m_ready !== 1'b1)
            failed[4] <= 1;
        if (h_valid === 1'b1 && h_ready !== 1'b0 && h_ready !== 1'b1)
