    end else failed[4] <= 1;
end

reg armed=0, reset_post=0;
reg [5:0] saved_ok=6'b111111;
reg [7:0] bytes_q[0:127];
reg lasts_q[0:127];
reg [33:0] headers_q[0:31];
reg [6:0] bw=0,br=0;
reg [5:0] bc=0;
reg [4:0] hw=0,hr=0;
reg [5:0] hc=0;
reg [3:0] in_len=0;
