  check_now[4]=((rst==0)||(rst==1)) & ((s_valid==0)||(s_valid==1)) &
   ((s_ready==0)||(s_ready==1)) & ((m_ready==0)||(m_ready==1)) & ((h_ready==0)||(h_ready==1));
  if(rst===1'b1) check_now[4]=check_now[4] & (s_valid==0);
  if(rst!==1'b1 && ss) check_now[4]=check_now[4] & (s_valid==1) & (source_now==sp);
