end
assign active={6{armed}};
assign ok=saved_ok & check_now;
always @(posedge clk) begin
 armed<=1;
 saved_ok<=saved_ok & check_now;
 reset_post<=(rst===1'b1);
 if(rst===1'b1) begin
  bw<=0; br<=0; bc<=0; hw<=0; hr<=0; hc<=0; in_len<=0;
  ms<=0; hs<=0; ss<=0; tail<=0; overflow<=0;
