 bad=0;
 if(seen) begin
  if(((rst!==1'b0)&&(rst!==1'b1)) ||
     ((s_valid!==1'b0)&&(s_valid!==1'b1)) ||
     ((s_ready!==1'b0)&&(s_ready!==1'b1)) ||
     ((m_ready!==1'b0)&&(m_ready!==1'b1)) ||
     ((h_ready!==1'b0)&&(h_ready!==1'b1)) ||
     ((m_valid!==1'b0)&&(m_valid!==1'b1)) ||
     ((h_valid!==1'b0)&&(h_valid!==1'b1))) bad[4]=1;
