   end
   if(rst===1'b0) begin
    if(hold_m&&((m_valid!==1'b1)||({m_last,m_data}!==saved_m))) bad[3]=1;
    if(hold_h&&((h_valid!==1'b1)||(hv!==saved_h))) bad[3]=1;
   end
  end
