 seen<=1;
 failed<=failed|bad;
 reset_edge<=(rst===1'b1);
 if(rst===1'b1) begin
  iw<=0; mr<=0; hr<=0; il<=0; mp<=0;
  data_frames<=0; header_frames<=0; early_done<=0;
  hold_m<=0; hold_h<=0; hold_s<=0; tail<=0;
