  hold_m<=(m_valid===1'b1)&&(m_ready===1'b0);
  hold_h<=(h_valid===1'b1)&&(h_ready===1'b0);
  hold_s<=(s_valid===1'b1)&&(s_ready===1'b0);
  saved_m<={m_last,m_data}; saved_h<=hv; saved_s<={s_last,s_data};
