reg armed=0, reset_post=0;
reg [5:0] bad=0;
reg [5:0] fail_now;
reg [6:0] iw=0,dr=0,hr=0;
reg [3:0] ip=0,dp=0;
reg [63:0] bytes_q[0:63];
reg [3:0] size_q[0:63];
reg ms=0,hs=0;
reg [8:0] saved_m=0;
reg [33:0] saved_h=0;
reg [7:0] tail=0;
