  if(dp<dn) begin bk=1; eb=bytes_q[dr[5:0]][dp*8 +: 8]; end
  else if(dd!=0 && dp<olen) begin bk=1; eb=0; end
  if(dp==7) el=1;
  else if(dd!=0) el=(dp==olen-1);
 end
 hn=0; hl=0; eh=0;
