   if(ip<12 && dd<63 && hd<63) begin
    if(ip<8) bytes_q[iw[5:0]][ip*8 +: 8]<=s_data;
    if(s_last===1'b1) begin
     size_q[iw[5:0]]<=ip+1'b1;
